<template>
  <div class="app-container returns-page">
    <el-alert v-if="error || pendingError" :title="error || pendingError" type="error" :closable="false" class="mb16" />
    <el-alert v-if="pending" :title="t('上次操作的结果尚未确认，请重试原请求。', 'The previous result is unconfirmed. Retry the original request.')" type="warning" :closable="false" class="mb16"><el-button :loading="busy" @click="retry">{{ t('重试当前操作', 'Retry pending operation') }}</el-button></el-alert>
    <div class="toolbar"><el-input v-model="keyword" clearable :placeholder="t('退货单号', 'Return reference')" :aria-label="t('搜索退货单', 'Search returns')" @keyup.enter="search" /><el-button @click="search">{{ t('搜索', 'Search') }}</el-button><el-button v-if="can('add')" type="primary" :disabled="blocked" @click="start">{{ t('登记退货', 'Register return') }}</el-button></div>
    <el-table v-loading="loading" :data="rows" border row-key="id" :aria-label="t('退货单列表', 'Returns')">
      <el-table-column prop="reference" :label="t('退货单号', 'Return reference')" min-width="170" fixed="left" /><el-table-column prop="orderReference" :label="t('原订单', 'Original order')" min-width="160" /><el-table-column prop="sku" label="SKU" min-width="140" /><el-table-column :label="t('状态', 'Status')" min-width="150"><template #default="{row}">{{ status(row.status) }}</template></el-table-column>
      <el-table-column v-for="col in counters" :key="col.key" :prop="col.key" :label="t(col.zh,col.en)" width="115" /><el-table-column :label="t('操作', 'Actions')" width="100" :fixed="isNarrow ? false : 'right'"><template #default="{row}"><el-button v-if="can('query')" link type="primary" @click="open(row.id)">{{ t('查看', 'View') }}</el-button></template></el-table-column>
    </el-table>
    <el-pagination v-if="total" v-model:current-page="page" :total="total" :page-size="20" layout="total, prev, pager, next" @current-change="load" class="pages" />

    <el-dialog v-model="newOpen" :title="t('登记客户退货', 'Register customer return')" width="min(640px, 94vw)" :close-on-click-modal="false" :close-on-press-escape="!busy" :show-close="!busy">
      <el-alert v-if="formError" :title="formError" type="error" :closable="false" class="mb16" />
      <el-form label-position="top" :disabled="blocked" @submit.prevent>
        <el-form-item :label="t('原发货订单', 'Original despatched order')"><el-select v-model="form.order" filterable remote :remote-method="findOrders" :aria-label="t('原发货订单', 'Original despatched order')" @change="selectOrder"><el-option v-for="o in orders" :key="o.id" :value="o.id" :label="o.reference" /></el-select></el-form-item>
        <el-form-item :label="t('退货商品', 'Returned product')"><el-select v-model="form.product" filterable :disabled="!selectedOrder" :aria-label="t('退货商品', 'Returned product')"><el-option v-for="o in selectedOrder?.lines || []" :key="o.product" :value="o.product" :label="orderLineLabel(o)" /></el-select></el-form-item>
        <div class="grid"><el-form-item :label="t('退货单号', 'Return reference')"><el-input v-model="form.reference" :aria-label="t('新退货单号', 'New return reference')" maxlength="120" /></el-form-item><el-form-item :label="t('预计退回数量', 'Expected return quantity')"><el-input-number :key="String(blocked)" v-model="form.quantity" :min="1" :max="10000000" :precision="0" :aria-label="t('预计退回数量', 'Expected return quantity')" /></el-form-item></div>
        <el-form-item :label="t('退货原因', 'Return reason')"><el-input v-model="form.reason" type="textarea" maxlength="500" :aria-label="t('退货原因', 'Return reason')" /></el-form-item>
      </el-form>
      <template #footer><el-button :disabled="busy" @click="newOpen=false">{{ t('关闭', 'Close') }}</el-button><el-button type="primary" :disabled="blocked" :loading="busy" @click="create">{{ t('保存退货单', 'Save return') }}</el-button></template>
    </el-dialog>

    <el-drawer v-model="opened" :title="t('退货处理', 'Return processing')" size="min(1160px, 100%)" :close-on-click-modal="!busy" :close-on-press-escape="!busy" :show-close="!busy">
      <template v-if="detail">
        <el-alert v-if="formError" :title="formError" type="error" :closable="false" class="mb16" />
        <div class="heading"><h3>{{ detail.reference }}</h3><el-tag>{{ status(detail.status) }}</el-tag><el-button :disabled="busy" @click="open(detail.id)">{{ t('刷新记录', 'Refresh return') }}</el-button></div>
        <p>{{ detail.orderReference }} · {{ detail.sku }} · {{ detail.clientName }} · {{ detail.warehouseName }}</p>
        <div class="totals"><span v-for="col in counters" :key="col.key">{{ t(col.zh,col.en) }} <strong>{{ detail[col.key] }}</strong></span><span>{{ t('隔离待处理', 'Held for disposition') }} <strong>{{ detail.held }}</strong></span></div>
        <el-alert type="info" :closable="false" :title="t('实物先收进隔离库位，检验后再上架或报废。原批次、串号及入库时间全程保留。', 'Receive into quarantine, inspect, then restock or scrap. Original batch, serial and receipt age are retained.')" class="mb16" />
        <p v-if="detail.rates" class="rates">{{ t('本单退货处理费', 'Return handling rates') }}: {{ detail.currency }} {{ detail.rates.returnFirst }} {{ t('首件', 'first item') }} / {{ detail.rates.returnAdditional }} {{ t('续件；首件费只收一次。', 'additional item; first rate charged once.') }}</p>
        <el-button v-if="returnOpen(detail) && detail.received < detail.quantity && can('receive')" type="primary" :disabled="blocked" @click="prepare('receive')">{{ t('签收进入隔离', 'Receive into quarantine') }}</el-button>
        <el-alert v-if="expiredReceipts" type="warning" :closable="false" class="mb16" :title="t('本单含已过期商品。上架遵循商品优先、客户兜底的效期策略：禁止过期会拦截，提醒模式会保留警示及处置记录。', 'This return includes expired stock. The product expiry policy overrides the client policy: BlockExpired prevents restocking; Warn retains the warning in disposition evidence.')" /><h3>{{ t('收货与检验', 'Receipts and inspection') }}</h3>
        <el-table :data="detail.receipts" border :aria-label="t('退货收货记录', 'Return receipts')">
          <el-table-column prop="locationName" :label="t('隔离库位', 'Quarantine location')" min-width="150" fixed="left" /><el-table-column v-for="col in tracking" :key="col.key" :prop="col.key" :label="t(col.zh,col.en)" min-width="115" />
          <el-table-column prop="quantity" :label="t('实收', 'Received')" width="85" /><el-table-column prop="remaining" :label="t('待处置', 'Held')" width="85" /><el-table-column :label="t('检验', 'Inspection')" width="120"><template #default="{row}">{{ inspection(row.inspection) }}</template></el-table-column><el-table-column prop="inspectionReason" :label="t('检验说明', 'Inspection notes')" min-width="170" /><el-table-column prop="receivedAt" :label="t('签收时间', 'Return received')" min-width="190" />
          <el-table-column v-if="returnOpen(detail)" :label="t('操作', 'Actions')" width="190" :fixed="isNarrow ? false : 'right'"><template #default="{row}"><template v-if="returnOpen(detail) && row.remaining"><el-button v-if="!row.disposed && can('inspect')" link type="primary" :disabled="blocked" @click="prepare('inspect',row)">{{ t('检验', 'Inspect') }}</el-button><el-button v-if="row.inspection==='PASS' && can('restock')" link type="primary" :disabled="blocked" @click="prepare('restock',row)">{{ t('上架', 'Restock') }}</el-button><el-button v-if="row.inspection==='FAIL' && can('scrap')" link type="danger" :disabled="blocked" @click="prepare('scrap',row)">{{ t('报废', 'Scrap') }}</el-button></template></template></el-table-column>
        </el-table>
        <h3>{{ t('处置记录', 'Disposition history') }}</h3><el-table :data="detail.dispositions" border><el-table-column :label="t('处置', 'Disposition')" width="115"><template #default="{row}">{{ actionLabel(row.action) }}</template></el-table-column><el-table-column prop="quantity" :label="t('数量', 'Quantity')" width="85" /><el-table-column prop="locationName" :label="t('上架库位', 'Restock location')" min-width="150" /><el-table-column prop="reason" :label="t('说明', 'Reason')" min-width="200" /><el-table-column prop="createdAt" :label="t('时间', 'Time')" min-width="190" /></el-table>
        <h3>{{ t('原发货来源', 'Original despatch sources') }}</h3><el-table :data="detail.sources" border><el-table-column v-for="col in tracking" :key="col.key" :prop="col.key" :label="t(col.zh,col.en)" min-width="120" /><el-table-column prop="quantity" :label="t('原发货量', 'Shipped')" width="110" /><el-table-column prop="returned" :label="t('累计退回', 'Returned so far')" width="125" /><el-table-column prop="remaining" :label="t('可退余量', 'Returnable')" width="110" /><el-table-column prop="receivedAt" :label="t('原入库时间', 'Original receipt age')" min-width="200" /></el-table>
        <p v-if="detail.closeReason || detail.cancelReason">{{ t('结案说明', 'Closure notes') }}: {{ detail.closeReason || detail.cancelReason }}</p>
      </template>
      <template #footer><el-button :disabled="busy" @click="opened=false">{{ t('关闭', 'Close') }}</el-button><template v-if="returnOpen(detail)"><el-button v-if="!detail.received && can('cancel')" type="danger" plain :disabled="blocked" @click="prepare('cancel')">{{ t('取消退货单', 'Cancel return') }}</el-button><el-button v-if="detail.received && !detail.held && can('close')" type="primary" :disabled="blocked" @click="prepare('close')">{{ t('退货结案', 'Close return') }}</el-button></template></template>
    </el-drawer>

    <el-dialog v-model="operationOpen" :title="actionLabel(operation)" width="min(600px, 94vw)" append-to-body :close-on-click-modal="false" :close-on-press-escape="!busy" :show-close="!busy">
      <el-alert v-if="formError" :title="formError" type="error" :closable="false" class="mb16" />
      <el-form v-if="detail" label-position="top" :disabled="blocked" @submit.prevent>
        <template v-if="operation==='receive'"><el-form-item :label="t('核对原发货批次或串号', 'Match original shipment batch or serial')"><el-select v-model="work.allocation" filterable :aria-label="t('原发货来源', 'Original despatch source')"><el-option v-for="s in detail.sources.filter(s=>s.remaining>0)" :key="s.id" :value="s.id" :label="sourceLabel(s)" /></el-select></el-form-item></template>
        <el-form-item v-if="['receive','restock'].includes(operation)" :label="operation==='receive'?t('隔离保管库位', 'Quarantine custody location'):t('上架库位', 'Restock location')"><el-select v-model="work.location" filterable remote :remote-method="findLocations" :aria-label="t('目标库位', 'Destination location')"><el-option v-for="o in locations" :key="o.id" :value="o.id" :label="o.label" /></el-select></el-form-item>
        <el-form-item v-if="['receive','restock','scrap'].includes(operation)" :label="t('本次数量', 'Quantity this time')"><el-input-number :key="operation+String(blocked)" v-model="work.quantity" :min="1" :max="10000000" :precision="0" :aria-label="t('本次数量', 'Quantity this time')" /></el-form-item>
        <el-form-item v-if="operation==='inspect'" :label="t('检验结果', 'Inspection result')"><el-radio-group v-model="work.result" :aria-label="t('检验结果', 'Inspection result')"><el-radio value="PASS">{{ t('合格，可申请上架', 'Passed, eligible for restocking') }}</el-radio><el-radio value="FAIL">{{ t('不合格，保留隔离或报废', 'Failed, hold or scrap') }}</el-radio></el-radio-group></el-form-item>
        <el-form-item v-if="operation!=='receive'" :label="t('操作说明', 'Reason')"><el-input v-model="work.reason" type="textarea" maxlength="500" :aria-label="t('操作说明', 'Reason')" /></el-form-item>
        <template v-if="operation==='close' && detail.received<detail.quantity"><el-alert type="warning" :closable="false" :title="t('还有商品未退回。短收结案后，未收数量可重新登记退货。', 'Some goods have not arrived. Closing a short return releases the unreceived quantity for a future RMA.')" /><el-checkbox v-if="user.id===1" v-model="work.approveShortfall">{{ t('管理员确认按实收数量结案', 'Administrator approves shortfall closure') }}</el-checkbox><p v-else>{{ t('短收结案需要管理员确认。', 'Shortfall closure requires an administrator.') }}</p></template>
        <el-alert v-if="operation==='scrap'" type="warning" :closable="false" :title="t('确认实物已报废后提交，系统将扣减隔离库存并保留记录。', 'Submit after physical disposal. This removes held stock and retains the evidence.')" />
      </el-form>
      <template #footer><el-button :disabled="busy" @click="operationOpen=false">{{ t('关闭', 'Close') }}</el-button><el-button :type="operation==='scrap'?'danger':'primary'" :disabled="blocked" :loading="busy" @click="perform">{{ t('确认提交', 'Confirm operation') }}</el-button></template>
    </el-dialog>
  </div>
</template>

<script setup>
import { computed, onMounted, onUnmounted, reactive, ref, toRaw, watch } from 'vue'
import { ElMessage } from 'element-plus'
import auth from '@/plugins/auth'
import useUserStore from '@/store/modules/user'
import { bilingual as t } from '@/warehouse/i18n'
import { rejectedBeforeCommit } from '@/warehouse/inventory'
import { returnOpen, newReturnPayload, returnActionPayload, returnPendingKey, readPendingReturn } from '@/warehouse/returns'
import { listReturns, getReturn, createReturn, actionReturn, listWarehouseOrders, getWarehouseOrder, getWarehouseLookups } from '@/api/warehouse'
const viewport=window.matchMedia('(max-width: 600px)'),isNarrow=ref(viewport.matches),resizeViewport=()=>{isNarrow.value=viewport.matches}
onMounted(()=>viewport.addEventListener('change',resizeViewport));onUnmounted(()=>viewport.removeEventListener('change',resizeViewport))
const user=useUserStore(),can=a=>auth.hasPermi('warehouse:returns:'+a)
const rows=ref([]),total=ref(0),page=ref(1),keyword=ref(''),loading=ref(false),busy=ref(false),error=ref(''),formError=ref(''),pendingError=ref(''),pending=ref(null),detail=ref(null),opened=ref(false),newOpen=ref(false),operationOpen=ref(false),operation=ref(''),orders=ref([]),selectedOrder=ref(null),locations=ref([])
const form=reactive({order:'',product:'',reference:'',quantity:1,reason:''}),work=reactive({receipt:'',allocation:'',location:'',quantity:1,result:'',reason:'',approveShortfall:false})
const expiredReceipts=computed(()=>detail.value?.receipts.some(r=>r.expiry&&r.expiry<new Date().toISOString().slice(0,10)))
const blocked=computed(()=>busy.value||!!pending.value||!!pendingError.value)
const counters=[{key:'quantity',zh:'预退数量',en:'Expected'},{key:'received',zh:'已收数量',en:'Received'},{key:'restocked',zh:'已上架',en:'Restocked'},{key:'scrapped',zh:'已报废',en:'Scrapped'}],tracking=[{key:'batch',zh:'批次',en:'Batch'},{key:'serial',zh:'串号',en:'Serial'},{key:'expiry',zh:'有效期',en:'Expiry'}]
const status=v=>t(({NEW:'待收货',PARTIALLY_RECEIVED:'部分收货',RECEIVED:'已收货',CLOSED:'已结案',CANCELLED:'已取消'})[v]||v,({NEW:'Awaiting receipt',PARTIALLY_RECEIVED:'Partially received',RECEIVED:'Received',CLOSED:'Closed',CANCELLED:'Cancelled'})[v]||v)
const inspection=v=>t(({PENDING:'待检验',PASS:'合格',FAIL:'不合格'})[v]||v,({PENDING:'Pending',PASS:'Passed',FAIL:'Failed'})[v]||v)
const actionLabel=v=>t(({receive:'签收进入隔离',inspect:'登记检验结果',restock:'退货上架',scrap:'退货报废',close:'退货结案',cancel:'取消退货单'})[v]||v,({receive:'Receive into quarantine',inspect:'Record inspection',restock:'Restock return',scrap:'Scrap return',close:'Close return',cancel:'Cancel return'})[v]||v)
const orderLineLabel=o=>{const shipped=selectedOrder.value?.allocations?.find(a=>a.product===o.product);return (o.sku||shipped?.sku||o.productName||shipped?.productName||o.product)+' · '+t('原发货 ','Shipped ')+o.quantity}
const sourceLabel=s=>[s.batch||t('无批次','No batch'),s.serial||t('无串号','No serial'),s.expiry||'',s.receivedAt,t('可退 ','Available ')+s.remaining].filter(Boolean).join(' · ')
const errors=e=>({return_required:t('请填写必填项。','Complete required fields.'),return_quantity:t('数量必须明确填写正整数。','Enter an explicit positive whole quantity.'),return_source:t('请选择原发货来源，数量不能超过可退余量。','Select the original source and stay within its returnable quantity.'),return_receipt:t('请选择仍有待处理数量的收货记录。','Select a receipt with held goods.'),return_inspection:t('检验结果或数量不符合本次处置要求。','Inspection or quantity does not permit this disposition.'),return_shortfall:t('请由管理员明确确认短收结案。','An administrator must explicitly approve the shortfall.'),return_held:t('仍有隔离商品未处理，不能结案或取消。','Held stock must be disposed before closure.'),return_closed:t('退货单已结束。','The return is closed.')})[e.message]||e.message||t('操作失败','Operation failed')
let listEpoch=0,detailEpoch=0,orderEpoch=0,locationEpoch=0
async function load(){const n=++listEpoch;loading.value=true;try{const r=await listReturns({pageNum:page.value,pageSize:20,keyword:keyword.value});if(n===listEpoch){rows.value=r.rows;total.value=r.total}}catch(e){error.value=errors(e)}finally{if(n===listEpoch)loading.value=false}}
function search(){page.value=1;load()}
async function open(id){const n=++detailEpoch;try{const r=await getReturn(id);if(n===detailEpoch){detail.value=r.data;opened.value=true;formError.value=''}}catch(e){error.value=errors(e)}}
async function findOrders(q=''){const n=++orderEpoch;try{const r=await listWarehouseOrders({pageNum:1,pageSize:200,keyword:q});if(n===orderEpoch)orders.value=r.rows.filter(o=>o.status==='DESPATCHED'&&o.workflow==='JAVA_MANUAL_V1')}catch(e){formError.value=errors(e)}}
async function selectOrder(id){form.product='';selectedOrder.value=null;try{const r=await getWarehouseOrder(id);if(form.order===id)selectedOrder.value=r.data}catch(e){formError.value=errors(e)}}
async function findLocations(q=''){const n=++locationEpoch,mode=operation.value,head=detail.value;if(!head)return;try{const r=await getWarehouseLookups('locations',q,{warehouse:head.warehouse});if(n===locationEpoch)locations.value=r.data.filter(o=>(!o.client||o.client===head.client)&&o.active!==false&&(mode==='receive'?o.type==='Quarantine'&&o.custodyOnly:o.type!=='Quarantine'&&!o.custodyOnly))}catch(e){formError.value=errors(e)}}
function start(){Object.assign(form,{order:'',product:'',reference:'',quantity:1,reason:''});selectedOrder.value=null;formError.value='';newOpen.value=true;findOrders()}
function prepare(action,receipt){operation.value=action;Object.assign(work,{receipt:receipt?.id||'',allocation:'',location:'',quantity:1,result:'',reason:'',approveShortfall:false});formError.value='';locations.value=[];operationOpen.value=true;if(['receive','restock'].includes(action))findLocations()}
function keep(value){sessionStorage.setItem(returnPendingKey(user.id),JSON.stringify(value));pending.value=value}
async function send(retrying){try{const p=structuredClone(toRaw(pending.value));const r=p.type==='create'?await createReturn(p.payload):await actionReturn(p.id,p.payload);sessionStorage.removeItem(returnPendingKey(user.id));pending.value=null;error.value='';formError.value='';newOpen.value=false;operationOpen.value=false;detail.value=r.data;opened.value=true;ElMessage.success({message:t('退货记录已保存','Return saved'),grouping:true});await load()}catch(e){if(!retrying&&rejectedBeforeCommit(e)){sessionStorage.removeItem(returnPendingKey(user.id));pending.value=null;formError.value=errors(e)}else formError.value=errors(e)+' · '+t('结果尚未确认，请重试原请求。','Result unconfirmed. Retry the original request.');error.value=formError.value}}
async function retry(){if(busy.value||!pending.value||!can(pending.value.type==='create'?'add':pending.value.payload.action))return;busy.value=true;try{await send(true)}finally{busy.value=false}}
async function create(){if(blocked.value||!can('add'))return;busy.value=true;try{keep({type:'create',payload:newReturnPayload(form,crypto.randomUUID())});await send(false)}catch(e){formError.value=errors(e)}finally{busy.value=false}}
async function perform(){if(blocked.value||!can(operation.value))return;busy.value=true;try{keep({type:'action',id:detail.value.id,payload:returnActionPayload(detail.value,operation.value,work,crypto.randomUUID())});await send(false)}catch(e){formError.value=errors(e)}finally{busy.value=false}}
watch(()=>user.id,()=>{pending.value=null;detail.value=null;opened.value=false;restore()})
function restore(){try{pending.value=readPendingReturn(sessionStorage,user.id);pendingError.value=''}catch{pendingError.value=t('无法读取未确认请求，请先保留浏览器会话并联系管理员核对。','The pending request could not be read. Preserve this browser session and contact an administrator.')}}
onMounted(()=>{restore();load()})
</script>
<style scoped>
.toolbar,.heading,.totals{display:flex;align-items:center;gap:12px;flex-wrap:wrap}.toolbar{margin-bottom:16px}.toolbar .el-input{max-width:300px}.heading h3{margin:0}.totals{margin:20px 0}.totals span{padding:8px 12px;background:var(--el-fill-color-light);border-radius:4px}.totals strong{margin-left:8px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}.el-select{width:100%}.pages{margin-top:18px}.mb16{margin-bottom:16px}.rates{line-height:1.6}.returns-page :deep(.el-drawer__body){min-width:0}.returns-page :deep(.el-drawer__footer){display:flex;justify-content:flex-end;flex-wrap:wrap;gap:8px}.el-radio-group{display:flex;flex-wrap:wrap}.el-radio{height:auto;min-height:32px;white-space:normal}@media(max-width:600px){.grid{grid-template-columns:1fr}.toolbar .el-input{max-width:100%;width:100%}.pages{max-width:100%;overflow:auto}.totals{gap:8px}.totals span{padding:6px 8px}.app-container{padding:12px}}
</style>
